// Convierte el error técnico en un aviso para el equipo humano, en lenguaje de negocio.
const e = $input.first().json || {};
const ex = e.execution || {};
const err = ex.error || {};
const quien = (e.workflow && e.workflow.name) || 'un workflow del sistema';
const paso = ex.lastNodeExecuted || 'paso no identificado';
const motivo = String(err.message || 'sin detalle').slice(0, 300);
const asunto = 'ALERTA del sistema de atención - falla en ' + quien;
const cuerpo = [
  'Se detectó una falla que el sistema no pudo resolver solo.',
  '',
  'Dónde: ' + quien + ' (paso: ' + paso + ')',
  'Qué pasó: ' + motivo,
  'Cuándo: ' + new Date().toISOString(),
  'Ejecución: ' + (ex.url || ex.id || 'sin dato'),
  '',
  'Qué hacer: revisá la ejecución, corregí la causa (por ejemplo, una credencial vencida o un servicio caído) y volvé a enviar la consulta. '
  + 'El sistema no duplica registros ni envíos, así que reenviar es seguro.',
  '',
  'Este aviso no incluye datos de pacientes.'
].join('\n');
return [{ json: { asunto, cuerpo } }];
